# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs):
    return [v * v for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: digest
def digest(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return digest(shape(render(gather(raw))))

