        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'total': 89, 'grade': 'high'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'total': 0, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 289, 'grade': 'high'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'total': 0, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 144, 'grade': 'high'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'total': 1604, 'grade': 'high'})

